1→//! op-agents: Agent implementations for op-dbus
//!
//! This crate provides agent types and the factory function to create them.
//! Agents are domain-specific AI assistants that can be invoked via D-Bus or MCP.

pub mod agent_catalog;
pub mod agent_registry;
pub mod agent_schema;
pub mod agents;
10→pub mod dbus_service;
pub mod dynamic;
pub mod generator;
pub mod router;
pub mod security;
pub mod unified;

// Re-export key types
pub use agent_catalog::{AgentDescriptor, builtin_agent_descriptors};
pub use agent_registry::{AgentRegistry, AgentStatus, load_default_specs};
20→pub use agent_schema::AgentOperationSchema;
pub use agents::base::{AgentContext, AgentTask, AgentTrait, TaskResult};
pub use router::{AgentsServiceRouter, AgentsState, create_router};
pub use unified::{AgentCategory, GLOBAL_REGISTRY, UnifiedAgentRegistry};

/// Create an agent by type name
///
/// Dispatches dynamically through `unified::GLOBAL_REGISTRY`, which lazily builds
/// agents from shared trait components (PersonaAgent, ExecutionAgent, OrchestrationAgent)
/// and wraps them in `UnifiedAgentAdapter` to satisfy `AgentTrait`.
30→///
/// # Arguments
/// * `agent_type` - The type of agent (e.g., "rust-pro", "memory", "sequential-thinking")
/// * `agent_id` - Unique identifier for this agent instance
///
/// # Returns
/// A boxed agent trait object, or error if type is unknown
pub fn create_agent(
    agent_type: &str,
    agent_id: String,
40→) -> Result<Box<dyn AgentTrait + Send + Sync>, String> {
    let catalog_type = if agent_type.contains('_') {
        agent_type.replace('_', "-")
    } else {
        agent_type.to_string()
    };

    let lookup = catalog_type.as_str();
    if let Some(unified_agent) = unified::GLOBAL_REGISTRY.get_normalized(lookup) {
        return Ok(Box::new(unified::UnifiedAgentAdapter::new(
50→            unified_agent,
            lookup.to_string(),
            agent_id,
        )));
    }

    Err(format!("Unknown agent type: {agent_type}"))
}

/// List all available agent types
60→pub fn list_agent_types() -> Vec<&'static str> {
    let mut ids = unified::GLOBAL_REGISTRY.list_ids();
    ids.sort();
    ids
}

#[cfg(test)]
mod tests {
    use super::*;

70→    #[test]
    fn test_create_agent() {
        let agent = create_agent("memory", "test-1".to_string());
        assert!(agent.is_ok());
        let agent = agent.unwrap();
        assert_eq!(agent.agent_type(), "memory");
    }

    #[test]
    fn test_create_agent_underscore_variant() {
80→        let agent = create_agent("rust_pro", "test-2".to_string());
        assert!(agent.is_ok());
    }

    #[test]
    fn test_unknown_agent() {
        let agent = create_agent("unknown-agent", "test-3".to_string());
        assert!(agent.is_err());
    }

90→    #[test]
    fn test_list_agent_types() {
        let types = list_agent_types();
        assert!(types.contains(&"memory"));
        assert!(types.contains(&"rust-pro"));
        assert!(types.contains(&"sequential-thinking"));
        assert!(types.len() > 50); // We have many agents
    }

    #[test]
100→    fn test_create_agent_unified_fallback() {
        let agent = create_agent("python-executor", "test-4".to_string());
        assert!(agent.is_ok());
        assert_eq!(agent.unwrap().agent_type(), "python-executor");
    }
}

1→//! Agent catalog for tool registration.
//!
//! Builds descriptors from the unified registry via `create_agent`, including
//! per-operation JSON Schemas.

use crate::agent_schema::{AgentOperationSchema, infer_category, schemas_for_operations};
use crate::unified::{self, AgentCategory};
use crate::{AgentTrait, create_agent, list_agent_types};

10→/// Minimal descriptor for tool registration + schema export.
#[derive(Debug, Clone)]
pub struct AgentDescriptor {
    pub agent_type: String,
    pub name: String,
    pub description: String,
    pub operations: Vec<String>,
    pub category: AgentCategory,
    /// Typed JSON Schema per operation (MCP / plugin contract).
    pub operation_schemas: Vec<AgentOperationSchema>,
20→}

impl AgentDescriptor {
    pub fn schema_for(&self, operation: &str) -> Option<&AgentOperationSchema> {
        self.operation_schemas.iter().find(|s| s.name == operation)
    }
}

fn describe_agent(agent: &dyn AgentTrait) -> AgentDescriptor {
    let agent_type = agent.agent_type().to_string();
30→    let operations = agent.operations();
    let category = unified::GLOBAL_REGISTRY
        .get_normalized(&agent_type)
        .map(|a| a.category())
        .unwrap_or_else(|| infer_category(&agent_type, &operations));
    let description = agent.description().to_string();
    let operation_schemas = schemas_for_operations(category, &operations, &description);

    AgentDescriptor {
        agent_type,
40→        name: agent.name().to_string(),
        description,
        operations,
        category,
        operation_schemas,
    }
}

/// List built-in agents suitable for MCP/tool exposure.
pub fn builtin_agent_descriptors() -> Vec<AgentDescriptor> {
50→    let mut out = Vec::new();
    // Deduplicate on the *canonical* agent_type() — list ids and unified ids
    // can alias the same concrete agent (e.g. go-pro / golang-pro).
    let mut seen = std::collections::HashSet::new();

    let mut push_created = |agent: Box<dyn AgentTrait + Send + Sync>| {
        let canonical = agent.agent_type().to_string();
        if seen.insert(canonical) {
            out.push(describe_agent(agent.as_ref()));
        }
60→    };

    for agent_type in list_agent_types() {
        match create_agent(agent_type, "catalog".to_string()) {
            Ok(agent) => push_created(agent),
            Err(err) => tracing::warn!(agent_type, error = %err, "catalog skip"),
        }
    }

    for id in unified::GLOBAL_REGISTRY.list_ids() {
70→        match create_agent(id, "catalog".to_string()) {
            Ok(agent) => push_created(agent),
            Err(err) => tracing::warn!(agent = id, error = %err, "unified catalog skip"),
        }
    }

    out.sort_by(|a, b| a.agent_type.cmp(&b.agent_type));
    out
}

