50→/// Map a path's extension / well-known file names to domain terms.
pub fn language_terms(path: &str) -> Vec<String> {
    let lower = path.to_ascii_lowercase();
    let mut out: Vec<String> = Vec::new();
    let ext = lower.rsplit('.').next().unwrap_or("");
    let mut push = |s: &str| {
        if !out.iter().any(|o| o == s) {
            out.push(s.to_string());
        }
    };
60→    match ext {
        "rs" => {
            push("rust");
            push("cargo");
        }
        "py" => push("python"),
        "ts" | "tsx" => {
            push("typescript");
            push("javascript");
        }
70→        "js" | "jsx" | "mjs" => push("javascript"),
        "go" => push("go"),
        "sh" | "bash" => {
            push("shell");
            push("bash");
        }
        "sql" => push("sql"),
        "proto" => {
            push("grpc");
            push("protobuf");
80→        }
        "toml" if lower.ends_with("cargo.toml") => {
            push("rust");
            push("cargo");
        }
        "json" | "yaml" | "yml" | "toml" => push("config"),
        "md" => push("docs"),
        _ => {}
