                    entry.1 += 1;
                } else {
                    domains.push((d.clone(), 1));
180→                }
            }
        }
    }
    domains.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    let domains: Vec<String> = domains.into_iter().map(|(d, _)| d).take(4).collect();
    let name = if domains.is_empty() {
