        if section.is_empty() {
            continue;
        }
        prompt.push_str(match kind {
            PieceKind::Behavior => "## How you work\n",
            PieceKind::Knowledge => "## What you know\n",
            PieceKind::Capability => "## Tools you may direct\n",
210→            PieceKind::Example => "",
