            .get(1)
            .map(|m| m.as_str().trim().to_string())
            .unwrap_or_default();
        let items_text = cap.get(2).map(|m| m.as_str()).unwrap_or("");

        let items: Vec<String> = items_text
            .lines()
            .filter_map(|line| {
180→                let trimmed = line.trim();
                if trimmed.starts_with('-') || trimmed.starts_with('*') {
